// cache: extraction_cache table access, shared by every extraction path.

use std::path::Path;

use rusqlite::Connection;
use sha2::{Digest, Sha256};

use crate::schema::{ExtractedEdge, ExtractedNode, Extraction};
use astria_core::AstriaError;
use astria_paths::normalize;

// Generated by build.rs from Cargo.lock: the tree-sitter core version and
// per-language grammar crate versions. A grammar upgrade changes the
// generated table, which changes the tagged hashes below, which
// re-extracts exactly the affected language's cached files.
include!(concat!(env!("OUT_DIR"), "/grammar_versions.rs"));

/// SHA-256 hash of the file contents, versioned with the extraction scheme
/// tag so scheme changes (e.g. the id-format change in v2) invalidate all
/// cached extractions and force one clean re-extraction. Grammar-blind:
/// used for extraction routes with no parser dependency (docs, manifests,
/// media, office) and as a plain content hash by the semantic pass.
pub fn file_hash(path: &Path) -> Result<String, AstriaError> {
    let bytes = std::fs::read(path)?;
    let mut hasher = Sha256::new();
    hasher.update(astria_core::EXTRACTION_HASH_VERSION.as_bytes());
    hasher.update([0u8]);
    hasher.update(&bytes);
    Ok(format!("{:x}", hasher.finalize()))
}

/// Parser fingerprint for one extraction language: the tree-sitter core
/// version (a runtime upgrade affects every grammar), the grammar crate
/// that parses the language, and the language name itself — a project
/// extension override can remap a suffix between languages that share a
/// grammar crate (C and Metal both parse with tree-sitter-cpp), and the
/// remap must still invalidate the affected files. Languages with no
/// grammar dependency get a stable placeholder, so their cache keys stay
/// content-driven.
pub fn grammar_fingerprint(language: &str) -> String {
    match GRAMMAR_VERSIONS.iter().find(|(name, _)| *name == language) {
        Some((_, tag)) => format!("{TREE_SITTER_CORE}|{tag}|{language}"),
        None => "unversioned".to_string(),
    }
}

/// Content hash that additionally mixes a parser fingerprint: cached AST
/// extractions are keyed by (rules, grammar, contents) so a grammar
/// upgrade re-extracts only the files that grammar parses, and unrelated
/// dependency changes invalidate nothing.
pub fn file_hash_tagged(path: &Path, tag: &str) -> Result<String, AstriaError> {
    let bytes = std::fs::read(path)?;
    let mut hasher = Sha256::new();
    hasher.update(astria_core::EXTRACTION_HASH_VERSION.as_bytes());
    hasher.update([0u8]);
    hasher.update(tag.as_bytes());
    hasher.update([0u8]);
    hasher.update(&bytes);
    Ok(format!("{:x}", hasher.finalize()))
}

/// Check the extraction_cache table. Returns cached Extraction if hit.
pub(crate) fn check_cache(db: &Connection, path: &Path, hash: &str) -> Option<Extraction> {
    let path_str = normalize(path);
    let mut stmt = db
        .prepare(
            "SELECT language, nodes, edges FROM extraction_cache WHERE file_path = ?1 AND content_hash = ?2",
        )
        .ok()?;
    stmt.query_row(rusqlite::params![&path_str, hash], |row| {
        let language: String = row.get(0)?;
        let nodes_json: String = row.get(1)?;
        let edges_json: String = row.get(2)?;
        Ok((language, nodes_json, edges_json))
    })
    .ok()
    .and_then(|(language, nodes_json, edges_json)| {
        let nodes: Vec<ExtractedNode> = serde_json::from_str(&nodes_json).ok()?;
        let edges: Vec<ExtractedEdge> = serde_json::from_str(&edges_json).ok()?;
        Some(Extraction {
            file_path: path.to_path_buf(),
            language,
            nodes,
            edges,
        })
    })
}

/// Save extraction result to the cache table.
pub(crate) fn save_cache(db: &Connection, path: &Path, hash: &str, extraction: &Extraction) {
    let path_str = normalize(path);
    let nodes_json = serde_json::to_string(&extraction.nodes).unwrap_or_default();
    let edges_json = serde_json::to_string(&extraction.edges).unwrap_or_default();
    let now = chrono_free_timestamp();

    if let Err(e) = db.execute(
        "INSERT OR REPLACE INTO extraction_cache (file_path, content_hash, language, nodes, edges, extracted_at) VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
        rusqlite::params![
            &path_str,
            hash,
            extraction.language,
            nodes_json,
            edges_json,
            now,
        ],
    ) {
        eprintln!("warning: failed to cache extraction for {}: {}", path_str, e);
    }
}

/// Simple timestamp without needing chrono.
fn chrono_free_timestamp() -> String {
    format!(
        "{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs()
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn grammar_fingerprints_are_language_specific() {
        // Every grammar-bearing language carries its crate name (and the
        // core version), so two languages never share a fingerprint and a
        // grammar bump invalidates only its own language.
        let rust = grammar_fingerprint("Rust");
        let python = grammar_fingerprint("Python");
        assert!(rust.contains("tree-sitter-rust"), "got: {rust}");
        assert!(python.contains("tree-sitter-python"), "got: {python}");
        assert_ne!(rust, python);
        // Both ride the same tree-sitter core runtime.
        assert!(rust.contains(TREE_SITTER_CORE));
        // Grammar-less routes get a stable placeholder instead of a
        // version-bearing tag.
        assert_eq!(grammar_fingerprint("pdf"), "unversioned");
    }

    #[test]
    fn tagged_hash_is_stable_and_tag_sensitive() {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("m.rs");
        std::fs::write(&file, b"fn main() {}").unwrap();

        let a = file_hash_tagged(&file, "tree-sitter@1|tree-sitter-rust@2").unwrap();
        let b = file_hash_tagged(&file, "tree-sitter@1|tree-sitter-rust@2").unwrap();
        assert_eq!(a, b, "same tag + content must hash identically");

        // A grammar version bump alone re-keys the cache entry...
        let bumped =
            file_hash_tagged(&file, "tree-sitter@1|tree-sitter-rust@3").unwrap();
        assert_ne!(a, bumped);
        // ...and the tagged hash never collides with the grammar-blind one,
        // so AST and non-AST cache keys live in disjoint spaces.
        let plain = file_hash(&file).unwrap();
        assert_ne!(a, plain);
    }
}
